{"command": "cd /tmp/sv-da273b6fc6f34c2c8853d4f40b0de866 && \
# Use nm to get dynamic symbols from the stripped binary, then look up our addresses
# Frames in libmonosgen-2.0.so: #01 0x222098, #02 0x222234, #03 0x19bac0, #06 0x19bc14
nm -D symbols/libmonosgen-2.0.so | sort | head -5
echo "---"
# Look up each address against sorted symbols
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo -n "pc $addr -> "
  # Find the symbol just before this address
  nm -D --defined-only symbols/libmonosgen-2.0.so | awk -v addr="$addr" '
    BEGIN { sub("0x","",addr); best_name="??"; best_addr=0 }
    { 
      a = strtonum("0x"$1)
      target = strtonum("0x"addr)
      if (a <= target && a > best_addr) { best_addr = a; best_name = $3 }
    }
    END { printf "%s+0x%x\n", best_name, strtonum("0x"addr) - best_addr }
  '
done", "description": "Symbolicate mono frames"}

{"command": "cd /tmp/sv-da273b6fc6f34c2c8853d4f40b0de866 && \
# Use llvm-objdump to get all function labels, then look up our addresses
llvm-objdump -d --no-show-raw-insn symbols/libmonosgen-2.0.so 2>/dev/null | grep "^[0-9a-f]* <" | sed 's/://;s/ </ /' | sed 's/>//' > /tmp/mono_funcs.txt
wc -l /tmp/mono_funcs.txt
echo "---"
# Now find nearest function for each address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo -n "pc $addr -> "
  awk -v addr="$addr" '
    BEGIN { sub("0x","",addr); best_name="??"; best_addr=0 }
    { 
      a = strtonum("0x"$1)
      target = strtonum("0x"addr)
      if (a <= target && a > best_addr) { best_addr = a; best_name = $2 }
    }
    END { printf "%s+0x%x\n", best_name, strtonum("0x"addr) - best_addr }
  ' /tmp/mono_funcs.txt
done", "description": "Extract function labels from disassembly", "initial_wait": 60}
